class PlatePile {
    private val plates = mutableListOf<String>()

    fun push(plate: String) {
        plates.add(plate)
    }

    fun pop(): String {
        return plates.removeAt(plates.lastIndex)
    }

    fun isEmpty(): Boolean {
        return plates.isEmpty()
    }
}

fun main() {
    val pile = PlatePile()
    pile.push("plate 1")
    pile.push("plate 2")
    pile.push("plate 3")
    while (!pile.isEmpty()) {
        println("Took: ${pile.pop()}")
    }
}
